using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Text.Json;
using Ryujinx.Graphics.Gpu;
using Ryujinx.Memory;

// GpuContext's trim members (TrimCaches and its constants, control: Core 658, candidate: plus adapt_host_warning_trim)
// are compiled unchanged into GpuContextUnderTest (Trim.cs, generated by the test). Doubles: HostMemoryBudget (headroom and
// device share set per case), the logger, GraphicsConfig and one PhysicalMemory whose caches record each trim call.
namespace Ryujinx.Memory
{
    public enum MemoryPressureLevel { Normal = 0, Warning = 1, Critical = 2 }

    public static class HostMemoryBudget
    {
        public static ulong AvailableBytes;
        public static int DeviceAvailablePercent;
    }
}

namespace Ryujinx.Common.Logging
{
    public enum LogClass { Gpu }

    public struct Printer
    {
        public void Print(LogClass logClass, string message) => Logger.Lines.Add(message);
    }

    public static class Logger
    {
        public static readonly List<string> Lines = new();
        public static Printer? Debug = new Printer();
        public static Printer? Info = new Printer();
    }
}

namespace Ryujinx.Graphics.Gpu
{
    public static class GraphicsConfig
    {
        public static bool EnableHostMemoryBudgetTracking = true;
    }

    public sealed class TextureCacheDouble
    {
        public readonly List<string> Calls = new();
        public ulong Trim(MemoryPressureLevel level, bool freeOnly = false)
        {
            Calls.Add($"textures {level} freeOnly={freeOnly}");
            return 32UL << 20;
        }
        public ulong LastTrimKeptBytes => 0;
    }

    public sealed class BufferCacheDouble
    {
        public readonly List<string> Calls = new();
        public ulong Trim(MemoryPressureLevel level)
        {
            Calls.Add($"buffers {level}");
            return 8UL << 20;
        }
    }

    public sealed class PhysicalMemory
    {
        public readonly TextureCacheDouble TextureCache = new();
        public readonly BufferCacheDouble BufferCache = new();
    }

    public partial class GpuContextUnderTest
    {
        internal ConcurrentDictionary<ulong, PhysicalMemory> PhysicalMemoryRegistry { get; } = new();
    }
}

static class Program
{
    static int Main()
    {
        const ulong MiB = 1024 * 1024;
        var cases = new List<(MemoryPressureLevel level, ulong available, int device)>
        {
            (MemoryPressureLevel.Warning, 2102 * MiB, 11),  // pid 11152, 03:20:04
            (MemoryPressureLevel.Warning, 2102 * MiB, 8),
            (MemoryPressureLevel.Warning, 2102 * MiB, 12),
            (MemoryPressureLevel.Warning, 2102 * MiB, 13),
            (MemoryPressureLevel.Warning, 2102 * MiB, 27),
            (MemoryPressureLevel.Warning, 2375 * MiB, 7),   // pid 11152, 03:13:39 (periodic trim)
            (MemoryPressureLevel.Warning, 2102 * MiB, -1),
            (MemoryPressureLevel.Warning, 700 * MiB, 11),
            (MemoryPressureLevel.Warning, 200 * MiB, 30),
            (MemoryPressureLevel.Critical, 2102 * MiB, 11),
            (MemoryPressureLevel.Normal, 2102 * MiB, 5),
        };
        var results = new List<Dictionary<string, object>>();
        foreach (var (level, available, device) in cases)
        {
            HostMemoryBudget.AvailableBytes = available;
            HostMemoryBudget.DeviceAvailablePercent = device;
            Ryujinx.Common.Logging.Logger.Lines.Clear();
            var context = new GpuContextUnderTest();
            var memory = new PhysicalMemory();
            context.PhysicalMemoryRegistry[1] = memory;
            context.TrimCaches(level);
            // A second report within the 2 s minimum interval does nothing.
            int before = memory.TextureCache.Calls.Count;
            context.TrimCaches(level);
            results.Add(new()
            {
                ["level"] = level.ToString(),
                ["availableMiB"] = available / MiB,
                ["device"] = device,
                ["calls"] = string.Join("; ", memory.TextureCache.Calls) + " | " + string.Join("; ", memory.BufferCache.Calls),
                ["secondWithin2s"] = memory.TextureCache.Calls.Count - before,
                ["log"] = string.Join(" / ", Ryujinx.Common.Logging.Logger.Lines),
            });
        }
        Console.WriteLine(JsonSerializer.Serialize(results));
        return 0;
    }
}
